<?php
namespace App\Console\Commands;
use App\Models\Invoice; use App\Models\User; use App\Notifications\OverdueInvoiceNotification; use Illuminate\Console\Command;
class NotifyOverdueInvoices extends Command{protected $signature='finance:notify-overdue-invoices';protected $description='Notify finance and assigned sales users about overdue invoices once per day';public function handle():int{$sent=0;Invoice::query()->with('lead')->where('balance_amount','>',0)->whereDate('due_date','<',today())->chunkById(100,function($invoices)use(&$sent){foreach($invoices as $invoice){$key='overdue_invoice:'.$invoice->id.':'.today()->toDateString();$users=User::query()->whereIn('role',['admin','account'])->get();if($invoice->lead?->assigned_to)$users->push(User::find($invoice->lead->assigned_to));foreach($users->filter()->unique('id') as $user){$exists=$user->notifications()->where('data','like','%"notification_key":"'.$key.'"%')->exists();if(!$exists){$user->notify(new OverdueInvoiceNotification($invoice,$key));$sent++;}}}});$this->info("Sent {$sent} overdue invoice notifications.");return self::SUCCESS;}}
